const normalize = (value) => value.replace(/\r\n/g, "\n");
const hash = (value) => createHash("sha256").update(normalize(value), "utf8").digest("hex");
const decode = (value) => Buffer.from(value, "base64").toString("utf8");
const timestamp = () => new Date().toISOString().replace(/[:.]/g, "-");
const npm = process.platform === "win32" ? "npm.cmd" : "npm";
const fail = (message) => { console.error(message); process.exitCode = 1; };

function mergeFile(entry, current) {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), "pfotentechnik-quality-ops-"));
  const currentFile = path.join(directory, "current");
  const baseFile = path.join(directory, "base");
  const targetFile = path.join(directory, "target");
  try {
    fs.writeFileSync(currentFile, normalize(current), "utf8");
    fs.writeFileSync(baseFile, decode(entry.beforeBase64), "utf8");
    fs.writeFileSync(targetFile, decode(entry.afterBase64), "utf8");
    const result = spawnSync("git", ["merge-file", "-p", currentFile, baseFile, targetFile], {
      encoding: "utf8",
      shell: false,
      windowsHide: true,
      maxBuffer: 20_000_000,
    });
    if (result.status !== 0 || /^(<{7}|={7}|>{7})/m.test(result.stdout || "")) {
      return { ok: false, reason: result.error?.message || "git merge-file meldete einen Konflikt." };
    }
    return { ok: true, content: normalize(result.stdout) };
  } finally {
    fs.rmSync(directory, { recursive: true, force: true });
  }
}

function run(command, args, cwd) {
  console.log(`> ${command} ${args.join(" ")}`);
  const result = spawnSync(command, args, { cwd, stdio: "inherit", shell: false, windowsHide: true });
  if (result.status !== 0) throw new Error(`Validierung fehlgeschlagen: ${command} ${args.join(" ")}`);
}

const root = process.cwd();
const marker = path.join(root, "apps", "pfotentechnik", "package.json");
if (!fs.existsSync(marker)) {
  fail("Abbruch: Bitte den Installer im Root von affiliate-template ausführen.");
} else {
  const states = [];
  const conflicts = [];
  for (const entry of ENTRIES) {
    const target = path.join(root, entry.file);
    if (!fs.existsSync(target)) {
      if (entry.action === "create") states.push({ entry, target, state: "change", source: null, content: decode(entry.afterBase64) });
      else conflicts.push({ file: entry.file, reason: "Datei fehlt." });
      continue;
    }
    const source = fs.readFileSync(target, "utf8");
    const currentHash = hash(source);
    if (currentHash === entry.afterHash) {
      states.push({ entry, target, state: "after", source, content: normalize(source) });
    } else if (entry.action === "create") {
      conflicts.push({ file: entry.file, reason: "Datei existiert bereits mit unbekanntem Inhalt." });
    } else if (currentHash === entry.beforeHash) {
      states.push({ entry, target, state: "change", source, content: decode(entry.afterBase64) });
    } else {
      const merged = mergeFile(entry, source);
      if (merged.ok) states.push({ entry, target, state: hash(merged.content) === currentHash ? "after" : "change", source, content: merged.content });
      else conflicts.push({ file: entry.file, reason: merged.reason });
    }
  }

  if (conflicts.length) {
    console.error("Abbruch: Für diese Dateien war kein konfliktfreier Drei-Wege-Merge möglich:");
    for (const conflict of conflicts) console.error(` - ${conflict.file}\n   ${conflict.reason}`);
    console.error("Es wurde nichts verändert. Bestehende Änderungen bleiben erhalten.");
    process.exitCode = 1;
  } else {
    const changed = states.filter((item) => item.state === "change");
    if (!changed.length) {
      console.log("Bereits installiert. Keine Änderungen erforderlich.");
    } else {
      const backupRoot = path.join(root, ".patch-backups", `${LABEL}-${timestamp()}`);
      fs.mkdirSync(backupRoot, { recursive: true });
      const applied = [];
      try {
        for (const item of changed) {
          if (item.source !== null) {
            const backup = path.join(backupRoot, item.entry.file);
            fs.mkdirSync(path.dirname(backup), { recursive: true });
            fs.copyFileSync(item.target, backup);
          }
          fs.mkdirSync(path.dirname(item.target), { recursive: true });
          const eol = item.source?.includes("\r\n") ? "\r\n" : os.EOL === "\r\n" ? "\r\n" : "\n";
          fs.writeFileSync(item.target, normalize(item.content).replace(/\n/g, eol), "utf8");
          applied.push(item);
        }

        for (const file of [
          "apps/pfotentechnik/scripts/quality-ops/sources.mjs",
          "apps/pfotentechnik/scripts/quality-ops/sync.mjs",
          "apps/pfotentechnik/src/lib/seo-copilot/quality-actions.mjs",
          "apps/pfotentechnik/src/lib/seo-copilot/quality-operations.mjs",
        ]) run(process.execPath, ["--check", file], root);
        run(npm, ["--workspace", "apps/pfotentechnik", "run", "test:seo-copilot"], root);
        run(npm, ["--workspace", "apps/pfotentechnik", "run", "quality-ops:sync"], root);

        console.log(`Installiert: ${changed.length} Dateien geändert.`);
        console.log(`Backup: ${backupRoot}`);
        console.log("Quality Operations ist aktiv. Der Astro-Build liest nur den kompakten Snapshot und führt keine Audits live aus.");
      } catch (error) {
        for (const item of applied.reverse()) {
          const backup = path.join(backupRoot, item.entry.file);
          if (fs.existsSync(backup)) fs.copyFileSync(backup, item.target);
          else if (item.entry.action === "create" && fs.existsSync(item.target)) fs.unlinkSync(item.target);
        }
        console.error("Validierung fehlgeschlagen. Die Repository-Dateien wurden automatisch zurückgerollt.");
        console.error(`Backup: ${backupRoot}`);
        fail(error instanceof Error ? error.message : String(error));
      }
    }
  }
}
